/* Settings presentation and bridges to existing calculation/display APIs. */
(()=>{'use strict';const $=id=>document.getElementById(id),angles=[0,180,120,90,60,150,30,45];let queued=false;
function parseOrb(value){const text=String(value).trim();if(/^\d+(?:\.\d+)?$/.test(text)){const n=Number(text);return n<=15?n:null;}const m=/^(\d{1,2})\s*[:°]\s*(\d{1,2})\s*[:′']\s*(\d{1,2}(?:\.\d+)?)\s*[″"]?$/.exec(text);if(!m||Number(m[2])>=60||Number(m[3])>=60)return null;const n=Number(m[1])+Number(m[2])/60+Number(m[3])/3600;return n<=15?n:null;}
function dms(value){let n=Math.round(Number(value)*3600);return Math.floor(n/3600)+':'+String(Math.floor(n%3600/60)).padStart(2,'0')+':'+String(n%60).padStart(2,'0');}
function syncEditors(){document.querySelectorAll('#astrosettings [data-dms-orb]').forEach(e=>{const source=$(e.dataset.dmsOrb);e.value=dms(source.value);e.setCustomValidity('');});document.querySelectorAll('#astrosettings [data-colour-hex]').forEach(e=>e.value=$(e.dataset.colourHex).value.toUpperCase());preview();}
function preview(){const box=$('settings-theme-preview');if(!box)return;for(const [css,id]of [['--sample-primary','setting-themeHeader'],['--sample-secondary','setting-themeButton'],['--sample-bg','setting-themeBackground'],['--sample-stripe','setting-themeStripe']])box.style.setProperty(css,$(id).value);}
function apply(){const p=KPPreferences.get();let style=$('kp-settings-column-choices');if(!style){style=document.createElement('style');style.id='kp-settings-column-choices';document.head.append(style);}style.textContent=(!p.rpShowSub?'#kp-live-ruling table :is(th,td):nth-child(5){display:none}':'')+(!p.rpShowSubSub?'#kp-live-ruling table :is(th,td):nth-child(6){display:none}':'');
 for(const a of angles){const orb=$('western-orb-'+a),enabled=$('western-angle-'+a);if(orb)orb.value=String(p['westernOrb'+a]);if(enabled)enabled.checked=p['westernEnabled'+a];}window.KPWesternAspects?.render();columns();}
function columns(){queued=false;const p=KPPreferences.get();document.querySelectorAll('#home table,#karyesh table,#south9 table,#kp-basic-calculations table').forEach(table=>{const row=table.querySelector('tr[data-planet],tr[data-house]');if(!row)return;const house=Boolean(row.dataset.house),hidden=new Set();for(const [fields,key]of [[['csl','CSL'],'sigShowCSL'],[['aspd','Aspd'],house?'houseShowAspd':'sigShowAspd'],[['aspg','Aspg'],'sigShowAspg'],[['conj','Conj'],house?'houseShowConj':'sigShowConj']])if(!p[key])fields.forEach(f=>hidden.add(f));const cells=[...row.children];cells.forEach((cell,i)=>{if(!cell.dataset.field)return;const hide=hidden.has(cell.dataset.field);table.querySelectorAll('tr').forEach(tr=>{const target=tr.children[i];if(target&&target.hidden!==hide)target.hidden=hide;});});});}
function schedule(){if(!queued){queued=true;requestAnimationFrame(columns);}}
function labels(){for(const root of document.querySelectorAll('#settings-pane-ruling,#settings-pane-aspects,#settings-theme-preview,.settings-search,.settings-preset-picker,#settings-tab-ruling,#settings-tab-aspects')){if(root.dataset.settingsEn)root.setAttribute('data-no-localize','');root.querySelectorAll('[data-settings-en]').forEach(e=>e.setAttribute('data-no-localize',''));}document.querySelectorAll('#settings-pane-themes details>summary').forEach(e=>e.setAttribute('data-no-localize',''));window.KPSettings?.setLanguage(KPPreferences.get().language);}
function init(){const shell=$('kp-settings-shell');if(!shell)return;const rail=shell.querySelector('.settings-rail');const mobile=document.createElement('label');mobile.className='settings-mobile-category';mobile.innerHTML='<span data-settings-en="Settings section" data-settings-mr="सेटिंग विभाग">Settings section</span><select id="settings-mobile-category" aria-label="Settings section"></select>';shell.querySelector('.settings-layout').before(mobile);const picker=mobile.querySelector('select');const syncPicker=()=>{const tabs=[...rail.querySelectorAll('[data-settings-tab]')];picker.replaceChildren(...tabs.filter(t=>!t.hidden).map(t=>new Option(t.textContent.trim(),t.dataset.settingsTab,t.getAttribute('aria-selected')==='true',t.getAttribute('aria-selected')==='true')));};picker.onchange=()=>{KPSettings.activate(picker.value);shell.querySelector('.settings-content').scrollTop=0;};new MutationObserver(syncPicker).observe(rail,{subtree:true,attributes:true,attributeFilter:['hidden','aria-selected'],childList:true,characterData:true});syncPicker();const search=document.createElement('label');search.className='settings-search';search.innerHTML='<span data-settings-en="Find a setting" data-settings-mr="सेटिंग शोधा">Find a setting</span><input id="settings-find" type="search" placeholder="Language, colours, aspects…" aria-label="Find a setting"><output aria-live="polite"></output>';shell.querySelector('.settings-heading').append(search);search.querySelector('input').oninput=e=>{const term=e.target.value.trim().toLocaleLowerCase();let count=0;for(const tab of rail.querySelectorAll('[data-settings-tab]')){const panel=$(tab.getAttribute('aria-controls')),match=!term||[tab.textContent,tab.dataset.settingsEn,tab.dataset.settingsMr,panel.textContent,...[...panel.querySelectorAll('[data-settings-en]')].map(n=>n.dataset.settingsEn)].join(' ').toLocaleLowerCase().includes(term);tab.hidden=!match;if(match)count++;}const active=rail.querySelector('[aria-selected="true"]');if(active?.hidden&&count)KPSettings.activate([...rail.querySelectorAll('[data-settings-tab]')].find(t=>!t.hidden).dataset.settingsTab);search.querySelector('output').textContent=term?(KPPreferences.get().language==='marathi'?'जुळणारे विभाग: ':'Sections found: ')+count:'';};
 for(const source of shell.querySelectorAll('input[type=color]')){const wrap=document.createElement('div');wrap.className='settings-colour-control';source.before(wrap);wrap.append(source);const hex=document.createElement('input');hex.type='text';hex.maxLength=7;hex.dataset.colourHex=source.id;hex.setAttribute('aria-label',source.id.replace('setting-','')+' hexadecimal colour');hex.pattern='#[0-9A-Fa-f]{6}';wrap.append(hex);hex.oninput=()=>{const valid=/^#[0-9a-f]{6}$/i.test(hex.value);hex.setCustomValidity(valid?'':'Enter a colour as #RRGGBB.');if(valid){source.value=hex.value;source.dispatchEvent(new Event('input',{bubbles:true}));}};source.addEventListener('input',()=>{hex.value=source.value.toUpperCase();hex.setCustomValidity('');preview();});}
 const swatches=['#417505','#4a90e2','#0f766e','#7c3aed','#dc2626','#d97706','#1e293b','#ffffff'];for(const id of ['setting-themeHeader','setting-themeButton']){const palette=document.createElement('div');palette.className='settings-swatches';for(const colour of swatches){const b=document.createElement('button');b.type='button';b.style.backgroundColor=colour;b.setAttribute('aria-label',colour);b.onclick=()=>{$(id).value=colour;$(id).dispatchEvent(new Event('input',{bubbles:true}));};palette.append(b);}$(id).parentElement.after(palette);}
 const sample=document.createElement('div');sample.id='settings-theme-preview';sample.className='settings-full';sample.setAttribute('aria-label','Theme preview');sample.innerHTML='<strong data-settings-en="Theme preview" data-settings-mr="रंगसंगती नमुना">Theme preview</strong><div class="sample-header" data-settings-en="Planet / House" data-settings-mr="ग्रह / भाव">Planet / House</div><div class="sample-row">☉ · 1, 5, 9</div><div class="sample-row">☽ · 2, 7, 11</div><span class="sample-action" data-settings-en="Action button" data-settings-mr="कृती बटण">Action button</span>';$('settings-pane-themes').querySelector('.settings-grid').prepend(sample);
 const themeGrid=$('settings-pane-themes').querySelector('.settings-grid'),mainFields=['setting-theme','setting-themeType','setting-themeHeader','setting-themeButton'].map(id=>$(id).closest('.settings-field'));const extra=document.createElement('details');extra.className='settings-accordion settings-full';extra.innerHTML='<summary data-settings-en="More colours and sidebar" data-settings-mr="इतर रंग व डावी बाजू">More colours and sidebar</summary><div class="settings-grid"></div>';for(const child of [...themeGrid.children])if(child!==sample&&!mainFields.includes(child))extra.querySelector('div').append(child);themeGrid.replaceChildren(...mainFields,sample,extra);
 const preset=document.createElement('label');preset.className='settings-field settings-preset-picker';preset.innerHTML='<span data-settings-en="Software preset" data-settings-mr="पूर्वनिश्चित मांडणी">Software preset</span><select id="settings-preset-choice"><option value="custom">Custom layout</option><option value="classic">Classic KP</option><option value="compact">Compact</option><option value="presentation">Presentation</option></select>';preset.querySelector('select').onchange=e=>{$('settings-preset-'+e.target.value)?.click();};$('settings-pane-presets').querySelector('.settings-preset-list').before(preset);
 shell.addEventListener('input',e=>{const editor=e.target.closest('[data-dms-orb]');if(!editor)return;const n=parseOrb(editor.value),source=$(editor.dataset.dmsOrb),valid=n!==null&&n<=Number(source.max);editor.setCustomValidity(valid?'':'Enter a valid D:M:S or decimal angle within the allowed range.');if(valid){source.value=String(n);source.dispatchEvent(new Event('input',{bubbles:true}));}});
 document.addEventListener('click',e=>{if(!e.target.closest('#settings-save'))return;const invalid=[...shell.querySelectorAll('[data-dms-orb],[data-colour-hex]')].find(n=>!n.checkValidity());if(invalid){e.preventDefault();e.stopImmediatePropagation();const pane=invalid.closest('.settings-pane');KPSettings.activate(pane.id.replace('settings-pane-',''));const details=invalid.closest('details');if(details)details.open=true;invalid.reportValidity();invalid.focus();}},true);
 shell.addEventListener('settings-draft-restored',syncEditors);window.addEventListener('kp-preferences-changed',()=>{apply();syncEditors();labels();});const observer=new MutationObserver(schedule);for(const id of ['home-planets','home-houses','karyesh','south9'])if($(id))observer.observe($(id),{childList:true,subtree:true});syncEditors();if(KPPreferences.isConfigured())apply();else columns();labels();window.KPLanguage?.localize(shell);}
window.KPEasySettings=Object.freeze({parseOrb,dms,refresh:columns});if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init);else init();
})();
